alter table public.clients drop constraint if exists clients_social_platforms_check; alter table public.clients add constraint clients_social_platforms_check check (social_platforms <@ array['instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x']::text[]); alter table public.social_connections drop constraint if exists social_connections_platform_check; alter table public.social_connections add constraint social_connections_platform_check check (platform in ('instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x')); alter table public.social_snapshots drop constraint if exists social_snapshots_platform_check; alter table public.social_snapshots add constraint social_snapshots_platform_check check (platform in ('instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x')); alter table public.social_posts drop constraint if exists social_posts_platform_check; alter table public.social_posts add constraint social_posts_platform_check check (platform in ('instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x')); alter table public.social_posts add column if not exists thumbnail_path text; alter table public.social_posts add column if not exists first_seen_at timestamptz; create table if not exists public.social_baselines ( client_id uuid not null references public.clients (id) on delete cascade, platform text not null check (platform in ('instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x')), followers bigint check (followers is null or followers >= 0), started_on date not null, updated_by uuid references public.profiles (id) on delete set null, updated_at timestamptz not null default now(), primary key (client_id, platform) ); alter table public.social_baselines enable row level security; drop policy if exists "social_baselines: team read" on public.social_baselines; create policy "social_baselines: team read" on public.social_baselines for select using (public.current_role() <> 'client' and public.can_see_client(client_id)); drop policy if exists "social_baselines: client read own" on public.social_baselines; create policy "social_baselines: client read own" on public.social_baselines for select using (public.current_role() = 'client' and client_id = public.current_client_id()); create table if not exists public.social_readings ( id uuid primary key default gen_random_uuid(), run_id uuid, client_id uuid not null references public.clients (id) on delete cascade, platform text not null check (platform in ('instagram', 'facebook', 'tiktok', 'youtube', 'linkedin', 'x')), kind text not null check (kind in ('profile', 'post')), url text not null, post_key text, taken_at timestamptz not null default now(), status text not null check (status in ('ok', 'flagged', 'failed', 'rejected')), followers bigint, following bigint, posts_count bigint, likes bigint, comments bigint, views bigint, stats jsonb not null default '[]'::jsonb, problem text, screenshot_path text, reviewed_by uuid references public.profiles (id) on delete set null, reviewed_at timestamptz ); create index if not exists social_readings_lookup on public.social_readings (client_id, platform, kind, taken_at desc); create index if not exists social_readings_review on public.social_readings (status, taken_at desc); alter table public.social_readings enable row level security; drop policy if exists "social_readings: team read" on public.social_readings; create policy "social_readings: team read" on public.social_readings for select using (public.current_role() <> 'client' and public.can_see_client(client_id)); drop policy if exists "social_readings: client read own" on public.social_readings; create policy "social_readings: client read own" on public.social_readings for select using (public.current_role() = 'client' and client_id = public.current_client_id() and status = 'ok'); create table if not exists public.scrape_runs ( id uuid primary key default gen_random_uuid(), trigger text not null check (trigger in ('schedule', 'manual')), client_id uuid references public.clients (id) on delete cascade, requested_by uuid references public.profiles (id) on delete set null, status text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed', 'skipped')), created_at timestamptz not null default now(), started_at timestamptz, finished_at timestamptz, reads int not null default 0, failures int not null default 0, note text ); create index if not exists scrape_runs_recent on public.scrape_runs (created_at desc); alter table public.scrape_runs enable row level security; drop policy if exists "scrape_runs: team read" on public.scrape_runs; create policy "scrape_runs: team read" on public.scrape_runs for select using (public.current_role() in ('ceo', 'operations_manager', 'staff')); create table if not exists public.ai_usage ( id bigserial primary key, at timestamptz not null default now(), feature text not null, client_id uuid references public.clients (id) on delete set null, platform text, read_kind text, model text not null, input_tokens integer not null default 0, output_tokens integer not null default 0, cost_usd numeric(14, 8) not null default 0, ok boolean not null, error text, run_id uuid ); create index if not exists ai_usage_at on public.ai_usage (at desc); alter table public.ai_usage enable row level security; drop policy if exists "ai_usage: finance read" on public.ai_usage; create policy "ai_usage: finance read" on public.ai_usage for select using (public.current_role() in ('ceo', 'operations_manager')); create table if not exists public.ai_settings ( id boolean primary key default true check (id), scraper_model text not null default 'claude-haiku-5-5', posts_per_profile integer not null default 3 check (posts_per_profile between 0 and 12), prices jsonb not null default '{
    "claude-haiku-5-5": {"input": 0.10, "output": 0.50},
    "claude-sonnet-5-5": {"input": 2.00, "output": 10.00},
    "claude-opus-5-5": {"input": 4.00, "output": 20.00}
  }'::jsonb, gbp_per_usd numeric(10, 4) not null default 0.79 check (gbp_per_usd > 0), monthly_budget_usd numeric(12, 2) not null default 10 check (monthly_budget_usd >= 0), updated_by uuid references public.profiles (id) on delete set null, updated_at timestamptz not null default now() ); insert into public.ai_settings (id) values (true) on conflict (id) do nothing; alter table public.ai_settings enable row level security; drop policy if exists "ai_settings: finance read" on public.ai_settings; create policy "ai_settings: finance read" on public.ai_settings for select using (public.current_role() in ('ceo', 'operations_manager')); drop policy if exists "ai_settings: finance edit" on public.ai_settings; create policy "ai_settings: finance edit" on public.ai_settings for update using (public.current_role() in ('ceo', 'operations_manager')) with check (public.current_role() in ('ceo', 'operations_manager')); create or replace function public.ai_spend_report(day_start timestamptz, month_start timestamptz, last_month_start timestamptz) returns jsonb language plpgsql stable security definer set search_path = public as $$ begin if auth.uid() is not null and coalesce(public.current_role(), '') not in ('ceo', 'operations_manager') then raise exception 'Only the CEO or operations manager can see AI spend.'; end if; return jsonb_build_object( 'today', (select coalesce(sum(cost_usd), 0) from public.ai_usage where at >= day_start), 'month', (select coalesce(sum(cost_usd), 0) from public.ai_usage where at >= month_start), 'last_month', (select coalesce(sum(cost_usd), 0) from public.ai_usage where at >= last_month_start and at < month_start), 'all_time', (select coalesce(sum(cost_usd), 0) from public.ai_usage), 'month_calls', (select count(*) from public.ai_usage where at >= month_start), 'month_failed', (select count(*) from public.ai_usage where at >= month_start and not ok), 'month_reads', (select count(*) from public.ai_usage where at >= month_start and feature like 'scraper%'), 'month_read_cost', (select coalesce(sum(cost_usd), 0) from public.ai_usage where at >= month_start and feature like 'scraper%'), 'by_client', ( select coalesce(jsonb_agg(row_to_json(x) order by x.cost desc), '[]'::jsonb) from ( select u.client_id, coalesce(c.name, 'No client') as name, sum(u.cost_usd) as cost, count(*) as calls from public.ai_usage u left join public.clients c on c.id = u.client_id where u.at >= month_start group by u.client_id, c.name ) x ), 'by_platform', ( select coalesce(jsonb_agg(row_to_json(x) order by x.cost desc), '[]'::jsonb) from ( select coalesce(platform, 'none') as platform, sum(cost_usd) as cost, count(*) as calls from public.ai_usage where at >= month_start group by 1 ) x ), 'by_feature', ( select coalesce(jsonb_agg(row_to_json(x) order by x.cost desc), '[]'::jsonb) from ( select feature, sum(cost_usd) as cost, count(*) as calls, count(*) filter (where not ok) as failed from public.ai_usage where at >= month_start group by 1 ) x ) ); end; $$; revoke all on function public.ai_spend_report(timestamptz, timestamptz, timestamptz) from public; grant execute on function public.ai_spend_report(timestamptz, timestamptz, timestamptz) to authenticated, service_role; do $$ begin if to_regclass('storage.buckets') is not null then insert into storage.buckets (id, name, public) values ('social-shots', 'social-shots', false) on conflict (id) do update set public = false; insert into storage.buckets (id, name, public) values ('social-thumbs', 'social-thumbs', true) on conflict (id) do update set public = true; end if; end $$;
